params.expression:
JSON.stringify({
  url: location.href,
  vals: Array.from(document.querySelectorAll('input[type=number]')).filter(i => i.offsetParent!==null).map(i => i.id + '=' + i.value).slice(0,8),
  active: document.activeElement ? document.activeElement.id : 'none',
  btns: Array.from(document.querySelectorAll('button')).filter(b => /otp/i.test((b.innerText||'').replace(/\s+/g,' '))).filter(b=>b.offsetParent!==null).map(b => (b.innerText||'').replace(/\s+/g,' ').trim() + '[' + b.disabled + ']').slice(0,5)
})
